"prompt.groupPostGuide": "Biến bắt buộc:\n• {groupName} — tên nhóm Facebook đang đăng bài\n\nĐặt mục tiêu ngay đầu Prompt, rồi nêu đối tượng, giọng điệu, độ dài và điều cấm. Luôn giữ biến {groupName}.\n\nThảo luận: Dựa vào tên nhóm {groupName}, hãy viết bài 2-3 câu nêu một góc nhìn và kết bằng câu hỏi mở để mọi người chia sẻ kinh nghiệm.\nCâu tương tác: Dựa vào tên nhóm {groupName}, hãy viết một câu hỏi ngắn, gần gũi, dễ trả lời và khuyến khích thành viên kể trải nghiệm.\nHỏi–đáp: Dựa vào tên nhóm {groupName}, hãy nêu vấn đề, bối cảnh ngắn và một câu hỏi cụ thể để xin lời khuyên.\n\nNên thêm: chỉ trả về nội dung bài, không bịa, không quảng cáo, không hashtag/URL/Markdown. Không bắt buộc phải viết theo mẫu hỏi–đáp.\n\nBiến tự động (không bắt buộc): {groupContext} — tóm tắt chủ đề nóng trong nhóm; nếu không ghi, hệ thống vẫn tự gắn ngữ cảnh nhóm đã học (khi bật Học).",
