"sales.promptLabel": "Prompt tạo bài — dùng {groupName}, {sourceText}, {productInfo}",
"prompt.salesGuide": "Biến bắt buộc:\n• {groupName} — tên nhóm Facebook đang đăng bán\n• {sourceText} — thông tin/bài đã cào từ tập dữ liệu\n• {productInfo} — ghi chú bổ sung bạn nhập (giá, tình trạng, yêu cầu...)\n\nBài bán hàng có 3 biến bắt buộc: {groupName} là nhóm đích, {sourceText} là thông tin gốc, {productInfo} là ghi chú bổ sung. Hãy nói rõ giọng điệu và mục tiêu: bán hàng, hỏi giá, xin tư vấn hoặc hỏi nhu cầu.\n\nVí dụ hỏi giá: Dựa trên {sourceText} và {productInfo}, viết bài 2-4 câu cho nhóm {groupName}, nêu đúng tình trạng rồi hỏi mức giá hợp lý.\nVí dụ hỏi nhu cầu: Viết bài tự nhiên cho {groupName}, vừa giới thiệu sản phẩm vừa hỏi thành viên đang cần loại này không.\n\nKhông bịa giá, thông số, bảo hành, địa điểm hay cam kết; chỉ trả về bài đăng, không lời giải thích/hashtag/URL/Markdown.",
