"fd.aiPromptHint": "Must include {postText}. If Tag Page/Group is set, use {tagName} so AI embeds the mention naturally (e.g. \"check out {tagName} for more\").",
"fd.aiPromptDefault": "Read the following post carefully and write a short, natural comment in English, directly addressing the main point or specific detail of the post (not generic), friendly and positive tone (1-2 sentences), no invented information, no ads: \"{postText}\"",
  "fd.aiTagPromptDefault": "Read the post carefully and write exactly 2 comment sentences in English. Sentence 1: mention ONE specific detail from the post (fact, number, author's point) — no generic openers. Sentence 2: connect that detail to \"{tagName}\" through a real shared topic between the post and {tagName} (same field, same experience, same audience). Write \"{tagName}\" verbatim, do NOT add @ in front (the system inserts the tag), placing the name in a DIFFERENT position each time (opening, mid-sentence, or closing) while staying natural. No cliches, no follow-baiting, no blatant ads, no hashtags. Return only the comment. Post: \"{postText}\"",
