"sales.promptLabel": "Post prompt — use {groupName}, {sourceText}, {productInfo}",
"prompt.salesGuide": "Required variables:\n• {groupName} — the Facebook group being sold to\n• {sourceText} — scraped content / product information from the dataset\n• {productInfo} — your extra notes (price, condition, requirements...)\n\nSales posts have three required variables: {groupName} is the target group, {sourceText} is the source information, and {productInfo} is your extra note. State the goal clearly: sell, ask for a price, request advice, or check demand.\n\nPrice question: Based on {sourceText} and {productInfo}, write 2-4 sentences for {groupName}, state the known condition and ask for a reasonable price.\nDemand question: Write a natural post for {groupName} that introduces the product and asks whether members need this type.\n\nDo not invent prices, specs, warranty, location or promises; return only the post, without explanation, hashtags, URLs or Markdown.",
"sales.chatTitle": "💬 Chat with AI to review sales posts",
"sales.chatInputLabel": "Message AI",
"sales.chatInputPh": "E.g. Rewrite it in a friendlier tone, keep the price-question style, and use only my information.",
