"bg.salesDefault": "Đọc thông tin sản phẩm và viết một bài đăng bán hàng tự nhiên bằng {language} cho nhóm \"{groupName}\". Nội dung theo hướng vừa chia sẻ nhu cầu bán vừa hỏi ý kiến thành viên, không bịa thông tin và chỉ trả về nội dung bài đăng. Thông tin sản phẩm: {sourceText}. Ghi chú thêm: {productInfo}.",
