"bg.noPostDetail": "Bình luận AI không bám chi tiết bài viết — đã chặn trước khi đăng",
  "bg.newsDefault": "Dựa vào tin tức sau, viết một bài đăng tường Facebook cá nhân bằng {language}, giọng đời thường như status của người thật (chia sẻ, nêu quan điểm, hỏi bạn bè). Bắt buộc dùng 1 chi tiết cụ thể trong tin (số liệu, sự việc, tên riêng), không sao chép nguyên văn, không bịa thêm số liệu ngoài tin, không hashtag, không URL, không Markdown, không lời dẫn của AI. Bài 3-6 câu, kết bằng 1 câu hỏi mở. Quy tắc thời gian: tuyệt đối không viết cụm giờ tương đối (cách đây..., mới đây, vừa xong, hôm nay/hôm qua nếu tin trong 24h); chỉ khi ngày đăng nguồn đã quá 24 giờ mới ghi rõ ngày gốc một cách tự nhiên. Chỉ trả về nội dung bài đăng. Tin: {newsText}",
  "bg.newsPhotoDefault": "Dựa vào tin tức sau, viết một bài đăng tường Facebook cá nhân kèm ảnh bằng {language}, giọng nhà đầu tư/chuyên gia chứng khoán chia sẻ quan điểm (gần gũi, không khô như báo). Cấu trúc: (1) mở bằng diễn biến chính + số liệu cụ thể trong tin; (2) phân tích tác động tới thị trường hoặc nhóm cổ phiếu liên quan; (3) nêu 1-2 kịch bản hoặc lưu ý rủi ro, ghi rõ là góc nhìn cá nhân; (4) kết bằng 1 câu hỏi mở. Mọi số liệu, tên riêng, sự kiện chỉ lấy trong tin, tuyệt đối không bịa; không hashtag, không URL, không Markdown, không lời dẫn của AI. Bài 120-250 từ. Quy tắc thời gian: tuyệt đối không viết cụm giờ tương đối (cách đây..., mới đây, vừa xong, hôm nay/hôm qua nếu tin trong 24h); chỉ khi ngày đăng nguồn đã quá 24 giờ mới ghi rõ ngày gốc một cách tự nhiên. Chỉ trả về nội dung bài đăng. Tin: {newsText}",
"bg.newsBgDefault": "Dựa vào tin tức sau, viết 1-2 câu đăng tường Facebook cá nhân bằng {language}, giọng đời thường, nêu 1 chi tiết cụ thể trong tin, không sao chép nguyên văn, không bịa số liệu, không hashtag, không URL. Không ghi giờ tương đối (cách đây..., mới đây...). Chỉ trả về nội dung. Tin: {newsText}",
"bg.fbRewriteDefault": "Viết lại bài Facebook sau bằng {language} theo giọng cá nhân, giữ trung thực chi tiết/số liệu/tên riêng, không sao chép nguyên văn, không bịa thêm, không hashtag/URL/Markdown, 120-250 từ, kết bằng 1 câu hỏi mở. Nếu có ảnh đính kèm, có thể nhắc 1 chi tiết nhìn thấy trong ảnh nhưng không bịa. Bài gốc: {newsText}",
"bg.fbOpinionDefault": "Đọc bài/ảnh Facebook sau và viết một bài quan điểm cá nhân bằng {language}: nêu rõ bạn đồng tình hay phản biện, dẫn 1 chi tiết cụ thể từ bài hoặc ảnh, giải thích lý do, không công kích cá nhân, không bịa số liệu, không hashtag/URL/Markdown, 100-200 từ, kết bằng 1 câu hỏi mở. Bài gốc: {newsText}",
