"bg.errKeyInvalid": "API key for {provider} is invalid. Create/copy the key again in Google AI Studio, paste only the key string (usually starting with AIza), then press Test API.",
"bg.errKeyInvalidVilao": "Vilao API key is invalid (wrong or revoked/disabled). Go to vilao.ai → API Keys to create/copy a new key (usually starting with sk-), paste it into the profile and press Test again.",
"bg.errPermDenied": "API key for {provider} lacks Gemini API access or is restricted by website/IP.",
  "bg.commentRules": "MANDATORY RULES: Return only the content of ONE complete comment. No intro, no explanation, no option lists, no Markdown, no 'Comment:' label, no quotation marks, no trailing exclamation mark. If the post content is thin or only an image description, stick to the concrete details available in one short sentence — never write generic filler.",
  "bg.postRules": "MANDATORY: Write like a natural discussion post. You may end with ONE question to invite replies, but NEVER answer it. Never use 'Q:'/'A:' labels, no Q/A format, no AI preamble, no Markdown, never narrate the act of writing (no 'I am writing...', 'here is the post...', 'as requested...' meta-talk).",
  "bg.topicAnchor": "MANDATORY TOPIC: This post is only for the group \"{groupName}\". Every sentence must tie directly to this group's topic — a reader must immediately tell it belongs to \"{groupName}\" and no other group. No generic writing.",
  "bg.scaffoldContent": "AI returned content with leftover drafting notes — skipped this group instead of posting garbage",
  "bg.aiContentGuard": "AI returned content with a preamble, UI chip, or explanation — blocked before posting",
  "bg.aiWrongLanguage": "AI returned the wrong language — blocked before posting",
  "bg.aiUnrewritten": "AI returned content too close to the source — blocked before posting",
  "bg.avoidRecent": "RECENTLY POSTED (must write COMPLETELY DIFFERENT: change opener, angle, closing question):",
"bg.postBgRules": "Prefer writing close to the upper limit of {max} CHARACTERS (target {min}-{max}, including spaces); if the thought is already complete, add only relevant detail, never repetition or meaningless padding. Use a SINGLE paragraph, no line breaks, no emoji, no hashtags, no links, so Facebook keeps the colored background.",
"bg.postBgFirst": "HARD LIMIT (highest priority, never exceed): at most {max} characters including spaces, exactly ONE paragraph, with one short easy question; keep the topic and one key point. Ignore any requirements about paragraph/sentence counts or outlines in the prompt below; keep only the topic, tone and 1 question.",
"bg.postBgSemantic": "Within that limit keep the topic, the key point/benefit or viewpoint, and a question inviting replies if there is room; compress before returning and never leave a cut-off sentence.",
 "bg.postBgExpand": "Rewrite the content below as ONE complete Vietnamese paragraph, target {min}-{max} characters including spaces and try to use close to {max}. Add only relevant detail that clarifies the topic, benefit/viewpoint, or discussion question; do not invent facts, repeat yourself, pad meaninglessly, or use URLs/hashtags/emoji/Markdown. Return only the post, with no preamble, heading, or explanation of any kind.",
 "bg.postBgRepair": "Compress the content below into ONE complete Vietnamese paragraph, target {min}-{max} characters including spaces. Keep the topic, key point/benefit or viewpoint and the question if there is room; remove repetition, never cut mid-sentence, and use no URLs/hashtags/emoji/Markdown. Return only the compressed post, with no preamble, heading, or explanation of any kind.",
 "bg.postBgHardRepair": "Rewrite the content below as ONE complete Vietnamese paragraph, with an absolute maximum of {max} characters including spaces. Keep only the topic and one clear key point; add a question only if it still fits. Never cut mid-sentence, and use no URLs/hashtags/emoji/Markdown. Return only the compressed post, with no preamble, heading, or explanation of any kind.",
"bg.postTooLong": "AI could not compress the post to {max} characters, so it was not posted to avoid a cut-off sentence.",
"bg.postOnlyContent": "Return only the post content.",
