"bg.noPostDetail": "AI comment doesn't reference the post — blocked before posting",
"bg.newsDefault": "Based on the news below, write a personal Facebook wall post in {language} with a natural everyday voice (sharing something, giving an opinion, asking friends). Must use 1 concrete detail from the news (numbers, facts, names), no verbatim copying, no invented figures, no hashtags, no URLs, no Markdown, no AI preamble. 3-6 sentences, end with 1 open question. Time rule: never write relative-time phrases (X ago, just now, today/yesterday if the news is within 24h); only when the source is older than 24 hours may you state its original date naturally. Return only the post content. News: {newsText}",
  "bg.newsPhotoDefault": "Based on the news below, write a personal Facebook wall post with photo in {language}, voice of a stock investor/expert sharing views (approachable, not dry like news). Structure: (1) open with the main development + concrete figures from the news; (2) analyze impact on the market or related stock groups; (3) give 1-2 scenarios or risk notes, marked as personal view; (4) end with 1 open question. All figures, names, events only from the news, never invent; no hashtags, no URLs, no Markdown, no AI preamble. 120-250 words. Time rule: never write relative-time phrases (X ago, just now, today/yesterday if the news is within 24h); only when the source is older than 24 hours may you state its original date naturally. Return only the post content. News: {newsText}",
"bg.newsBgDefault": "Based on the news below, write 1-2 sentences for a personal Facebook wall in {language}, everyday voice, one concrete detail from the news, no copying, no invented figures, no hashtags, no URLs. No relative-time phrases (X ago, just now...). Return only the content. News: {newsText}",
"bg.fbRewriteDefault": "Rewrite the following Facebook post in {language} in a personal voice, keep details/figures/names truthful, do not copy verbatim, do not invent, no hashtags/URLs/Markdown, 120-250 words, end with one open question. If an image is attached, you may mention one visible detail but never invent. Source post: {newsText}",
"bg.fbOpinionDefault": "Read the following Facebook post/image and write a personal opinion in {language}: state whether you agree or disagree, cite one concrete detail from the post or image, explain why, no personal attacks, no invented figures, no hashtags/URLs/Markdown, 100-200 words, end with one open question. Source post: {newsText}",
