// Content scripts/background: hydrate sớm + bám theo khi đổi ngôn ngữ giữa phiên.
try {
  if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.onChanged) {
    initI18n();
    chrome.storage.onChanged.addListener((changes, area) => {
      // store.js chuyển ghi sync→local nên nhận cả 2 area.
      if ((area === "sync" || area === "local") && changes.uiLang && changes.uiLang.newValue && I18N[changes.uiLang.newValue]) {
        I18N_LANG = changes.uiLang.newValue;
      }
    });
  }
} catch (_) { }
